pub struct PagedProjection<P:SnapshotProjection>{cursor:Option<P::Projection>,output:Option<P::Output>,close_reply:ReplyStash<Failure>,closing:bool}
impl<P:SnapshotProjection> Default for PagedProjection<P>{fn default()->Self{Self{cursor:None,output:None,close_reply:Default::default(),closing:false}}}
fn receiving_error(error:semio_framework_value::OriginalReceivingPrimary)->ValueError{let progress=error.retained_progress();match error.primary{Some(primary)=>primary,None=>match error.retirement_failure{Some(failure)=>failure.into_value_error(),None=>ValueError::literal(ValueRefusalKind::InvariantViolated,"original receiving edit refused").with_retained_progress(progress)}}}
fn absent_projection()->ValueError{invalid("semantic projection cursor absent")}
impl<P:SnapshotProjection> SemanticProjection<P> for PagedProjection<P>{
 fn birth_work_demand(&self)->Result<u64,ValueError>{P::projection_birth_work_demand()}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.cursor.as_ref().ok_or_else(absent_projection)?.take_work_demand()?.checked_add(1).ok_or_else(||invalid("semantic projection handoff work overflow"))}
 fn birth_demand(&self)->RetirementDemand{P::projection_birth_demand()}
 fn begin(&mut self,effect:Effect<'_,'_>)->Result<RetainedCloneProgress,ValueError>{let d=P::projection_birth_demand();if !retained_clone_grant_admits(effect.grant(),d){return Err(invalid("semantic projection cursor birth not funded"));}one(effect)?;self.cursor=Some(P::projection_seed());Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})}
 fn demands(&self,s:RetainedCloneRef<'_,P>,b:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{self.cursor.as_ref().ok_or_else(absent_projection)?.demands(s,b,maximum_work_units)}
 fn advance_work_demand(&self,s:RetainedCloneRef<'_,P>,body:usize,maximum_work_units:u64)->Result<Option<u64>,ValueError>{self.cursor.as_ref().ok_or_else(absent_projection)?.advance_work_demand(s,body,maximum_work_units).map(Some)}
 fn advance(&mut self,s:RetainedCloneRef<'_,P>,body:usize,effect:Effect<'_,'_>)->Result<RetainedCloneStep,Failure>{let maximum=effect.maximum_work_units();let cursor=self.cursor.as_mut().ok_or_else(absent_projection)?;complete(|reply|cursor.advance_into(s,body,maximum,effect,reply))?}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{let a=self.cursor.as_ref().ok_or_else(absent_projection)?.take_demand()?;let b=<P::Output as ProjectionOutput<P>>::placement_demand();Ok(RetirementDemand{copy_bytes:a.copy_bytes.checked_add(b.copy_bytes).ok_or_else(||invalid("semantic projection transfer copy overflow"))?,capacity_bytes:a.capacity_bytes.checked_add(b.capacity_bytes).ok_or_else(||invalid("semantic projection transfer capacity overflow"))?,release_bytes:a.release_bytes.checked_add(b.release_bytes).ok_or_else(||invalid("semantic projection transfer release overflow"))?,depth:a.depth.max(b.depth)})}
 fn take(&mut self,effect:Effect<'_,'_>)->Result<Option<(P,RetainedCloneProgress)>,ValueError>{let g=effect.grant();let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}let placement=<P::Output as ProjectionOutput<P>>::placement_demand();let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-placement.copy_bytes,maximum_capacity_bytes:g.maximum_capacity_bytes-placement.capacity_bytes,maximum_release_bytes:g.maximum_release_bytes-placement.release_bytes,..g};
  let cursor=self.cursor.as_mut().ok_or_else(absent_projection)?;let output=&mut self.output;let progress={let mut nested=effect.nested(child);match complete(|reply|cursor.take_into(output,&mut nested,reply))??{RetainedCloneStep::Complete(progress)=>progress,RetainedCloneStep::Progress(_)=>return Ok(None)}};
  let mut target=std::mem::MaybeUninit::uninit();let mut nested=effect.nested(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:placement.copy_bytes,maximum_capacity_bytes:placement.capacity_bytes,maximum_release_bytes:placement.release_bytes,maximum_depth:placement.depth});let RetainedCloneStep::Complete(placed)=complete(|reply|<P::Output as ProjectionOutput<P>>::place_into(output,&mut target,&mut nested,reply))?.map_err(|_|invalid("sealed original projection placement changed its admitted demand"))? else{return Err(invalid("sealed original projection placement changed its admitted demand"))};let mut total=progress.checked_add(placed)?;total.copied_items=1;Ok(Some((unsafe{target.assume_init()},total)))}
 fn begin_close(&mut self){self.closing=true;}
 fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{match self.cursor.as_ref(){Some(c)if !c.terminal_is_empty()=>if c.close_started(){c.close_demands(b)}else{c.begin_close_demand()},Some(_)=>Ok(header::<Option<P::Projection>>()),None=>Ok(Default::default())}}
 fn close_work_demand(&self,body:usize)->Result<Option<u64>,ValueError>{if !self.closing{return Ok(Some(0))}match self.cursor.as_ref(){Some(cursor)if !cursor.terminal_is_empty()=>if cursor.close_started(){cursor.close_work_demand(body).map(Some)}else{cursor.begin_close_work_demand().map(Some)},Some(_)=>Ok(Some(1)),None=>Ok(Some(0))}}
 fn close_step(&mut self,effect:Effect<'_,'_>)->semio_framework_value::OriginalRetirementPoll{let result=(||->Result<RetainedCloneStep,Exit>{let g=effect.grant();if !self.closing{return Ok(RetainedCloneStep::Progress(Default::default()));}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}match self.cursor.as_mut(){Some(c)if !c.terminal_is_empty()=>{let answer=if !c.close_started(){self.close_reply.run(|reply,recover|if recover{c.recover_begin_close_into(effect,reply)}else{c.begin_close_into(effect,reply)}.map(drop))?}else{self.close_reply.run(|reply,recover|if recover{c.recover_close_into(g.maximum_copy_bytes,effect,reply)}else{c.close_into(g.maximum_copy_bytes,effect,reply)}.map(drop))?};match answer{None=>Err(Exit::Pending(0)),Some(step)=>Ok(step.map(|step|RetainedCloneStep::Progress(step.progress()))?)}},Some(_)=>{one(effect)?;self.cursor=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))},None=>Ok(RetainedCloneStep::Complete(Default::default()))}})();Exit::settle(effect,result)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.cursor.is_none()&&self.output.is_none()&&!self.close_reply.pending()}
}
pub struct ClonedProjection<P:RetainedClone>{cursor:Option<Box<P::Cursor>>,birth:semio_framework_value::retained_clone::RetainedCloneBirthDemand,close_reply:ReplyStash<Failure>,closing:bool}
impl<P:RetainedClone> ClonedProjection<P>{pub fn new(birth:semio_framework_value::retained_clone::RetainedCloneBirthDemand)->Self{Self{cursor:None,birth,close_reply:Default::default(),closing:false}}}
fn absent_clone()->ValueError{invalid("semantic retained clone cursor absent")}
impl<P:RetainedClone> SemanticProjection<P> for ClonedProjection<P>{
 fn birth_work_demand(&self)->Result<u64,ValueError>{Ok(1)}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.cursor.as_ref().map_or(Ok(0),|cursor|cursor.take_work_demand())}
 fn birth_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<P::Cursor>()+size_of::<Box<P::Cursor>>(),capacity_bytes:self.birth.capacity_bytes+size_of::<P::Cursor>(),depth:self.birth.depth.max(1),..Default::default()}}
 fn begin(&mut self,effect:Effect<'_,'_>)->Result<RetainedCloneProgress,ValueError>{let g=effect.grant();let d=self.birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid("semantic retained clone cursor birth not funded"));}self.cursor=Some(Box::new(P::retained_clone_cursor()));Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})}
 fn demands(&self,s:RetainedCloneRef<'_,P>,b:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{self.cursor.as_ref().ok_or_else(absent_clone)?.advance_demands(s,b,maximum_work_units)}
 fn advance_work_demand(&self,s:RetainedCloneRef<'_,P>,body:usize,maximum_work_units:u64)->Result<Option<u64>,ValueError>{self.cursor.as_ref().ok_or_else(absent_clone)?.advance_work_demand(s,body,maximum_work_units).map(Some)}
 fn advance(&mut self,s:RetainedCloneRef<'_,P>,body:usize,effect:Effect<'_,'_>)->Result<RetainedCloneStep,Failure>{let maximum=effect.maximum_work_units();let cursor=self.cursor.as_mut().ok_or_else(absent_clone)?;complete(|reply|cursor.advance_into(s,body,maximum,effect,reply))?}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{self.cursor.as_ref().ok_or_else(absent_clone)?.take_demand()}
 fn take(&mut self,effect:Effect<'_,'_>)->Result<Option<(P,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(None);}let mut output=None;let mut slot=None;{let reply=semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut slot)?;let _complete=self.cursor.as_mut().ok_or_else(absent_clone)?.take(&mut output,effect,reply)?;}match slot.take(){Some(Ok(step))=>Ok(output.map(|owner|(owner,step.progress()))),Some(Err(error))=>Err(error),None=>Ok(None)}}
 fn begin_close(&mut self){self.closing=true;}
 fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{match self.cursor.as_ref(){Some(c)if !c.terminal_is_empty()=>if c.close_started(){Ok(RetirementDemand{copy_bytes:c.next_close_copy_byte_demand()?,capacity_bytes:c.next_close_capacity_byte_demand(b)?,release_bytes:c.next_close_release_byte_demand()?,depth:c.next_close_depth_demand()?})}else{c.begin_close_demand()},Some(_)=>Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<P::Cursor>>>(),release_bytes:size_of::<P::Cursor>(),depth:1,..Default::default()}),None=>Ok(Default::default())}}
 fn close_work_demand(&self,body:usize)->Result<Option<u64>,ValueError>{if !self.closing{return Ok(Some(0))}match self.cursor.as_ref(){Some(cursor)if !cursor.terminal_is_empty()=>if cursor.close_started(){cursor.close_work_demand(body).map(Some)}else{cursor.begin_close_work_demand().map(Some)},Some(_)=>Ok(Some(1)),None=>Ok(Some(0))}}
 fn close_step(&mut self,effect:Effect<'_,'_>)->semio_framework_value::OriginalRetirementPoll{let result=(||->Result<RetainedCloneStep,Exit>{let g=effect.grant();if !self.closing{return Ok(RetainedCloneStep::Progress(Default::default()));}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}match self.cursor.as_mut(){Some(c)if !c.terminal_is_empty()=>{let answer=if !c.close_started(){self.close_reply.run(|reply,recover|if recover{c.recover_begin_close_into(effect,reply)}else{c.begin_close_into(effect,reply)}.map(drop))?}else{self.close_reply.run(|reply,recover|if recover{c.recover_close_into(g.maximum_copy_bytes,effect,reply)}else{c.close_into(g.maximum_copy_bytes,effect,reply)}.map(drop))?};match answer{None=>Err(Exit::Pending(0)),Some(step)=>Ok(step.map(|step|RetainedCloneStep::Progress(step.progress()))?)}},Some(_)=>{one(effect)?;self.cursor=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))},None=>Ok(RetainedCloneStep::Complete(Default::default()))}})();Exit::settle(effect,result)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.cursor.is_none()&&!self.close_reply.pending()}
}
pub struct PagedSemanticEdit<P,M,E:PagedOneItemEdit<P,M>>{edit:E,closing:bool,marker:std::marker::PhantomData<fn()->(P,M)>}
impl<P,M,E:PagedOneItemEdit<P,M>> Default for PagedSemanticEdit<P,M,E>{fn default()->Self{Self{edit:E::default(),closing:false,marker:Default::default()}}}
impl<P:'static,M:'static,E:PagedOneItemEdit<P,M>> SemanticEdit<P,M> for PagedSemanticEdit<P,M,E>{
 fn birth_work_demand(&self)->u64{1}
 fn birth_demand(&self)->RetirementDemand{header::<bool>()}
 fn begin(&mut self,effect:Effect<'_,'_>)->Result<RetainedCloneProgress,ValueError>{let d=self.birth_demand();if !retained_clone_grant_admits(effect.grant(),d){return Err(invalid("semantic edit stage not funded"));}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})}
 fn post_mode(&self)->PagedOneItemPostMode{self.edit.post_mode()}
 fn demands(&self,b:RetainedCloneRef<'_,P>,m:RetainedCloneRef<'_,M>,p:PagedOneItemPostRead<'_,P>,body:usize)->Result<RetirementDemand,ValueError>{self.edit.advance_demands(b,m,p,body,u64::MAX)}
 fn advance(&mut self,b:RetainedCloneRef<'_,P>,m:RetainedCloneRef<'_,M>,p:PagedOneItemPost<'_,P>,body:usize,grant:RetainedCloneGrant,receiving:&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->Result<SemanticEditStep<M>,ValueError>{let result=self.edit.advance(b,m,p,body,grant,receiving).map_err(receiving_error);Ok(match result?{PagedOneItemEditStep::Progress(r)=>SemanticEditStep::Progress(r),PagedOneItemEditStep::Complete(r,row)=>SemanticEditStep::CompleteSingle(r,row),PagedOneItemEditStep::CompleteRows(r,rows)=>SemanticEditStep::Complete(r,rows,Vec::new(),false),PagedOneItemEditStep::CompleteOutcome(r,rows,messages)=>SemanticEditStep::Complete(r,rows,messages,false),PagedOneItemEditStep::RefusedOutcome(r,messages)=>SemanticEditStep::Refused(r,messages)})}
 fn last_turn_work(&self)->u64{self.edit.last_turn_work()}
 fn begin_close(&mut self){self.closing=true;self.edit.begin_close();}
 fn close_demand(&self,f:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,b:usize)->Result<RetirementDemand,ValueError>{self.edit.close_demands(f,b)}
 fn close_work_demand(&self,f:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,body:usize)->Result<u64,ValueError>{self.edit.close_work_demand(f,body)}
 fn close_step(&mut self,f:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,effect:Effect<'_,'_>)->semio_framework_value::OriginalRetirementPoll{self.edit.close_step(f,effect)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.edit.terminal_is_empty()}
}
pub struct ClonedSemanticEdit<P:RetainedClone,M,E:RetainedCloneEdit<P,M>>{factory:Option<Arc<E>>,cursor:Option<Box<E::Cursor>>,factory_close:Option<semio_framework_value::FactoryAuthority>,closing:bool,last_work:u64}
impl<P:RetainedClone,M,E:RetainedCloneEdit<P,M>> ClonedSemanticEdit<P,M,E>{pub fn new(factory:Arc<E>)->Self{Self{factory:Some(factory),cursor:None,factory_close:None,closing:false,last_work:0}}}
impl<P:RetainedClone,M:'static,E:RetainedCloneEdit<P,M>> SemanticEdit<P,M> for ClonedSemanticEdit<P,M,E>{
 fn birth_work_demand(&self)->u64{1}
 fn birth_demand(&self)->RetirementDemand{let d=self.factory.as_ref().unwrap().begin_demand();RetirementDemand{copy_bytes:size_of::<E::Cursor>()+size_of::<Box<E::Cursor>>(),capacity_bytes:d.capacity_bytes+size_of::<E::Cursor>(),depth:d.depth.max(1),..Default::default()}}
 fn begin(&mut self,effect:Effect<'_,'_>)->Result<RetainedCloneProgress,ValueError>{let g=effect.grant();let d=self.birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid("semantic retained edit birth not funded"));}let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<Box<E::Cursor>>(),maximum_capacity_bytes:g.maximum_capacity_bytes-size_of::<E::Cursor>(),..g};let(c,mut p)=self.factory.as_ref().unwrap().begin(child)?;self.cursor=Some(Box::new(c));p.copied_bytes=p.copied_bytes.max(d.copy_bytes);p.retained_capacity_bytes+=size_of::<E::Cursor>();Ok(p)}
 fn post_mode(&self)->PagedOneItemPostMode{PagedOneItemPostMode::Mutable}
 fn demands(&self,b:RetainedCloneRef<'_,P>,m:RetainedCloneRef<'_,M>,p:PagedOneItemPostRead<'_,P>,body:usize)->Result<RetirementDemand,ValueError>{self.cursor.as_ref().ok_or_else(||invalid("semantic retained edit cursor absent"))?.advance_demands(b,p.get(),m,body)}
 fn advance(&mut self,b:RetainedCloneRef<'_,P>,m:RetainedCloneRef<'_,M>,p:PagedOneItemPost<'_,P>,body:usize,g:RetainedCloneGrant,receiving:&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->Result<SemanticEditStep<M>,ValueError>{self.last_work=0;let p=p.mutable()?;let c=self.cursor.as_mut().ok_or_else(||invalid("semantic retained edit cursor absent"))?;let d=c.advance_demands(b,&*p,m,body)?;if !retained_clone_grant_admits(g,d){return Ok(SemanticEditStep::Progress(Default::default()));}let turn=probe_effect(receiving,g,|control,effect|{if let Err(error)=control.admit_turn_capacity(g.maximum_capacity_bytes){return(Err(error),effect.performed_work())}if d.capacity_bytes!=0{if let Err(error)=control.charge(d.capacity_bytes){return(Err(error),effect.performed_work())}}let result=c.advance(b,p,m,body,effect);(result,effect.performed_work())})?;let Some((result,work))=turn else{return Ok(SemanticEditStep::Progress(Default::default()))};self.last_work=u64::try_from(work).unwrap_or(u64::MAX);Ok(match result?{RetainedCloneEditStep::Progress(r)=>SemanticEditStep::Progress(r),RetainedCloneEditStep::Complete(r)=>{let rows=c.take_inverse().ok_or_else(||invalid("semantic retained edit omitted inverse"))?;SemanticEditStep::Complete(r,rows,Vec::new(),c.foreign_step_presence())}})}
 fn last_turn_work(&self)->u64{self.last_work}
 fn begin_close(&mut self){self.closing=true;if let Some(c)=self.cursor.as_mut(){c.cancel();let _=c.begin_close();}}
 fn close_demand(&self,_:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,b:usize)->Result<RetirementDemand,ValueError>{if let Some(c)=self.cursor.as_ref(){return if c.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<E::Cursor>>>(),release_bytes:size_of::<E::Cursor>(),depth:1,..Default::default()})}else{Ok(RetirementDemand{copy_bytes:c.next_close_copy_byte_demand()?,capacity_bytes:c.next_close_capacity_byte_demand(b)?,release_bytes:c.next_close_release_byte_demand()?,depth:c.next_close_depth_demand()?})};}if self.factory.is_some(){return Ok(header::<Arc<E>>());}self.factory_close.as_ref().map_or(Ok(Default::default()),|f|f.demands(b))}
 fn close_work_demand(&self,_:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,body:usize)->Result<u64,ValueError>{if !self.closing{return Ok(0)}if let Some(cursor)=self.cursor.as_ref(){return if cursor.terminal_is_empty(){Ok(1)}else{Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"retained edit cursor has no original close work quote"))}}if self.factory.is_some(){return Ok(1)}self.factory_close.as_ref().map_or(Ok(0),|owner|owner.next_computational_work(body))}
 fn close_step(&mut self,f:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,effect:Effect<'_,'_>)->semio_framework_value::OriginalRetirementPoll{let result=(||->Result<RetainedCloneStep,Exit>{let g=effect.grant();if !self.closing{return Ok(RetainedCloneStep::Progress(Default::default()));}let d=self.close_demand(f,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}if let Some(c)=self.cursor.as_mut(){if !c.terminal_is_empty(){return Ok(c.close_step(effect)?);}one(effect)?;self.cursor=None;}else if let Some(f)=self.factory.take(){one(effect)?;self.factory_close=Some(semio_framework_value::FactoryAuthority::new(f));}else if let Some(f)=self.factory_close.as_mut(){let s=Exit::resume(f.step(g.maximum_copy_bytes,effect))?;if f.terminal_is_empty(){self.factory_close=None;}return Ok(s);}Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})();Exit::settle(effect,result)}
 fn terminal_is_empty(&self)->bool{self.closing&&self.cursor.is_none()&&self.factory.is_none()&&self.factory_close.is_none()}
}

/// 🪢 Funds the metadata-free native semantic producer from the retained clone preparation factory.
impl<P,M,E> ArtifactReplayPreparationFactory<P,M> for RetainedClonePreparationFactory<P,M,E>
where P:RetainedClone,M:ArtifactCanonicalJsonTree+RetireOwned+Send+Sync+'static,E:RetainedCloneEdit<P,M>{
 fn preparation_birth_demand(&self)->semio_framework_value::RetirementDemand{
  type Producer<P,M,E>=NativeSemanticPreparation<P,M,ClonedProjection<P>,ClonedSemanticEdit<P,M,E>>;
  semio_framework_value::RetirementDemand{copy_bytes:size_of::<ArtifactReplayPreparationRequest<P,M>>()+size_of::<Producer<P,M,E>>()+size_of::<Arc<E>>(),capacity_bytes:size_of::<Producer<P,M,E>>(),depth:1,..Default::default()}
 }
 fn begin(&self,request:ArtifactReplayPreparationRequest<P,M>,grant:RetainedCloneGrant)->Result<(Box<dyn ArtifactReplayPreparation<P,M>>,RetainedCloneProgress),(ValueError,ArtifactReplayPreparationRequest<P,M>)>{
  let d=ArtifactReplayPreparationFactory::preparation_birth_demand(self);
  if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d){return Err((ValueError::literal(ValueRefusalKind::WorkLimit,"semantic retained clone producer birth not funded"),request));}
  let refusal=match request.input.borrow(){Ok(input)=>match self.edit.preflight(input.get(),HistoryLane::Document){Ok(footprint)if footprint.is_admissible()=>None,Ok(_)=>Some("semantic retained clone operation exceeds the one-item footprint"),Err(reason)=>Some(reason)},Err(error)=>return Err((error,request))};
  let projection=ClonedProjection::<P>::new(self.edit.snapshot_cursor_birth_demand());
  let edit=ClonedSemanticEdit::<P,M,E>::new(Arc::clone(&self.edit));
  let producer=match refusal{Some(reason)=>NativeSemanticPreparation::refused(request,projection,edit,reason),None=>NativeSemanticPreparation::new(request,projection,edit)};
  Ok((Box::new(producer),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))
 }
}
